1	/**
2	 * `run`: the whole pipeline, on one application, in one command.
3	 *
4	 * Every stage in this directory was proven on its own before this module
5	 * existed, and `migrate` reaches most of them only when each is opted into.
6	 * That is deliberate and stays: `migrate`'s exit-0 path has to remain runnable
7	 * with no registry, and a stage it was never asked for has to be recorded as
8	 * not run rather than implied. So this is the other entry beside it — the one
9	 * whose answer is "what does this application do when all nine stages are
10	 * asked for" — and it adds no migration decision of its own.
11	 *
12	 * Three properties are structural rather than convenient.
13	 *
14	 * **It composes; it does not reimplement.** Each stage here is the same
15	 * exported function the single-stage command composes, called with the same
16	 * declarations. A policy nobody declared refuses exactly where it refuses when
17	 * the stage is invoked alone, because it is the same guard.
18	 *
19	 * **The first refusing stage settles the run.** Its refusal is carried
20	 * verbatim, the exit code is 2, and every later stage is recorded not-run with
21	 * that stage named. Nothing here catches a refusal in order to keep going: a
22	 * chained run that stepped over a refused migration would report a lane the
23	 * pipeline declined to make.
24	 *
25	 * **One seam.** `runStage` is the only place a stage begins and ends. The
26	 * timestamps, the status and the refusal capture all live in it, so a later
27	 * reading that needs to count something per stage has one place to instrument
28	 * rather than nine call sites to find.
29	 */
30	
31	import { readFile } from 'node:fs/promises';
32	import * as path from 'pathe';
33	import {
34		COVERAGE_REPORT_SCHEMA,
35		coverageReportDigest,
36		type CoverageReport,
37	} from '../../../trust/src/coverage-report.ts';
38	import { analyzeApplication, fileExists } from './analyze.ts';
39	import { applyPlan } from './apply.ts';
40	import { runLaneBuild } from './build.ts';
41	import { establishEraCell, type EraCellDeclarations } from './era-cell.ts';
42	import { ingestApplicationSource, readFrontendRoot, type IngestDeclarations } from './ingest.ts';
43	import { writeLaneFiles } from './lane.ts';
44	import { readLicenceAtPin, type LicencePolicy } from './license.ts';
45	import { planLaneRuntime, runLaneInstall, type InstallPolicy } from './install.ts';
46	import { planApplication } from './plan.ts';
47	import { composeLane, displayPath } from './record.ts';
48	import {
49		EXIT_DEFECT,
50		EXIT_PROCEEDED,
51		EXIT_REFUSAL,
52		pipelineRefusalOf,
53		renderRefusal,
54		type PipelineRefusal,
55	} from './refusals.ts';
56	import { runLaneWitness } from './witness.ts';
57	
58	export const RUN_SCHEMA = 'versionless.run.v1';
59	
60	/**
61	 * The slot the coverage report occupies.
62	 *
63	 * `run` does not derive that document and does not regenerate the trust package
64	 * to refresh it: it points at what the guarded derivation emitted. Pointing is
65	 * the whole contract, so the three readings this seam can take are all recorded
66	 * as what they are — the report is there and internally consistent, it is there
67	 * and does not recompute to its own digest, or it is not there at all.
68	 */
69	export const RUN_COVERAGE_REPORT_SLOT = 'evidence/trust/current/coverage-report.json';
70	
71	export type RunReportSlot =
72		| Readonly<{ status: 'emitted'; slot: string; path: string; digest: string }>
73		| Readonly<{ status: 'not-yet-emitted' | 'stale'; slot: string; reason: string }>;
74	
75	/**
76	 * Read the emitted coverage report, or say honestly why this is not one.
77	 *
78	 * The digest is recomputed over the published record rather than trusted from
79	 * the field it carries, so a report edited after emission reads `stale` here
80	 * instead of being pointed at as if it were derived. What this cannot establish
81	 * is freshness with respect to *this* run: keeping the report current across a
82	 * rebuild is the generator's ordering problem, not this seam's.
83	 */
84	export async function readCoverageReportSlot(rootDir = '.'): Promise<RunReportSlot> {
85		const file = path.join(rootDir, RUN_COVERAGE_REPORT_SLOT);
86		let body: string;
87		try {
88			body = await readFile(file, 'utf8');
89		} catch {
90			return Object.freeze({
91				status: 'not-yet-emitted' as const,
92				slot: RUN_COVERAGE_REPORT_SLOT,
93				reason: 'no coverage report is published at the slot',
94			});
95		}
96		let report: CoverageReport;
97		try {
98			report = JSON.parse(body) as CoverageReport;
99		} catch {
100			return Object.freeze({
101				status: 'stale' as const,
102				slot: RUN_COVERAGE_REPORT_SLOT,
103				reason: 'the published coverage report is not readable JSON',
104			});
105		}
106		if (report.schemaVersion !== COVERAGE_REPORT_SCHEMA)
107			return Object.freeze({
108				status: 'stale' as const,
109				slot: RUN_COVERAGE_REPORT_SLOT,
110				reason: `the published coverage report carries schema ${String(report.schemaVersion)} rather than ${COVERAGE_REPORT_SCHEMA}`,
111			});
112		if (coverageReportDigest(report) !== report.integrity.canonicalDigest)
113			return Object.freeze({
114				status: 'stale' as const,
115				slot: RUN_COVERAGE_REPORT_SLOT,
116				reason: 'the published coverage report does not recompute to its own canonical digest',
117			});
118		return Object.freeze({
119			status: 'emitted' as const,
120			slot: RUN_COVERAGE_REPORT_SLOT,
121			path: RUN_COVERAGE_REPORT_SLOT,
122			digest: report.integrity.canonicalDigest,
123		});
124	}
125	
126	/**
127	 * The stages, in the order they run.
128	 *
129	 * The order is not a preference. Admission precedes composition because a
130	 * licence nobody read is a reason not to compose a lane at all; the cell
131	 * precedes the install because the install runs inside it; the witness is last
132	 * because there is nothing to witness until something has been emitted.
133	 */
134	export const RUN_STAGES = [
135		'analyze',
136		'ingest',
137		'license-at-pin',
138		'era-cell',
139		'plan',
140		'apply',
141		'install',
142		'build',
143		'witness',
144	] as const;
145	
146	export type RunStageName = (typeof RUN_STAGES)[number];
147	
148	/** Which stage owns which declaration. `run` forwards and owns none of them. */
149	export const RUN_STAGE_FLAGS: Readonly<Record<RunStageName, readonly string[]>> = Object.freeze({
150		analyze: Object.freeze([]),
151		ingest: Object.freeze([
152			'--source-root',
153			'--id',
154			'--frontend-root',
155			'--revision',
156			'--repository',
157			'--ref',
158			'--lockfile',
159			'--license',
160		]),
161		'license-at-pin': Object.freeze(['--frontend-root', '--license']),
162		'era-cell': Object.freeze(['--cell', '--node', '--arch']),
163		/**
164		 * `--cell` appears here as well as on the era-cell stage because both stages
165		 * read it, for different things: era-cell reads the Node line the cell
166		 * needs, and plan composes the changeset against the cell itself. Listing it
167		 * once would say one of the two stages ignores a declaration it does not.
168		 */
169		plan: Object.freeze(['--source-dir', '--template-dir', '--style-dir', '--entry', '--cell']),
170		apply: Object.freeze(['--out', '--materialize', '--compose-only']),
171		install: Object.freeze([
172			'--allow-remote-tarballs',
173			'--allow-install-scripts',
174			'--skip-install-scripts',
175			'--allow-peer-conflicts',
176			'--allow-foreign-lockfile',
177		]),
178		build: Object.freeze([]),
179		witness: Object.freeze([]),
180	});
181	
182	export type RunStageStatus = 'ran' | 'not-run' | 'refused' | 'defect';
183	
184	export type RunStageRow = Readonly<{
185		name: RunStageName;
186		status: RunStageStatus;
187		/** Why the stage did not run, or what broke in it. */
188		reason?: string;
189		refusal?: PipelineRefusal;
190		/** The record the stage itself produced, unaltered. */
191		record?: unknown;
192		startedAt: string;
193		endedAt: string;
194	}>;
195	
196	export type RunStagePlanRow = Readonly<{
197		name: RunStageName;
198		/** The declarations from this command line the stage is given. */
199		forwards: readonly string[];
200	}>;
201	
202	export type RunRecord = Readonly<{
203		schema: string;
204		flow: 'run';
205		outcome: 'proceeded' | 'refused' | 'defect' | 'not-run';
206		exitCode: number;
207		application: string;
208		lane: string;
209		/**
210		 * The two roots this run read, printed side by side so a reader can see
211		 * which tree each stage was given: the acquisition root is the unit of
212		 * provenance (journal, revision, licence, tree parity) and the frontend
213		 * root is the unit of composition (analyze, era-cell, plan, apply).
214		 */
215		roots: Readonly<{
216			source: string;
217			frontend: string;
218			frontendSource: 'declared' | 'read' | 'not-read';
219			frontendBasis: string;
220		}>;
221		dryRun: boolean;
222		stagePlan: readonly RunStagePlanRow[];
223		stages: readonly RunStageRow[];
224		refusal?: PipelineRefusal;
225		defect?: Readonly<{ stage: RunStageName; message: string }>;
226		report: RunReportSlot;
227		notEstablished: readonly string[];
228	}>;
229	
230	/** What the report slot does not establish, in each of its three readings. */
231	const REPORT_NOT_ESTABLISHED: Readonly<Record<RunReportSlot['status'], string>> = Object.freeze({
232		emitted: `The coverage report at ${RUN_COVERAGE_REPORT_SLOT} was emitted by the guarded derivation and recomputes to the digest recorded here. This run did not derive it, did not regenerate it, and establishes nothing about whether it is current with respect to this run.`,
233		stale: `A file exists at ${RUN_COVERAGE_REPORT_SLOT} and is not the report this run may point at: it does not recompute to its own canonical digest or does not carry the coverage schema. Nothing here establishes what a regenerated report would say.`,
234		'not-yet-emitted': `No coverage report is published at ${RUN_COVERAGE_REPORT_SLOT}. This run did not emit one; a reader who needs coverage has to derive it elsewhere.`,
235	});
236	
237	const RUN_NOT_ESTABLISHED: readonly string[] = Object.freeze([
238		'A stage recorded `ran` returned its own record. What that record establishes is what that stage states, and no more: this row adds no reading of its own on top of it.',
239		'A stage recorded `not-run` was not reached, because an earlier stage refused or broke. Nothing here establishes what it would have recorded.',
240		'Exit 2 is a refusal and exit 1 is a defect. A crash, a hang, or a tree that will not install is a defect even when it happens inside a stage that can also refuse.',
241		'The stage timestamps bound the wall-clock interval the seam observed around each stage. They are not a measurement of machine time and they are not comparable across hosts.',
242	]);
243	
244	export type RunDeclarations = Readonly<{
245		appRoot: string;
246		out: string;
247		/** The repository root the ingest stage reads; defaults to the app root. */
248		sourceRoot: string;
249		/**
250		 * Whether the apply stage copies the application into the lane first.
251		 *
252		 * `run` sets this true unless `--compose-only` was declared. It is the same
253		 * choice `migrate --materialize` makes and it is taken through the same
254		 * writer: `applyPlan`'s own `materialize` option. There is no second lane
255		 * writer here, and the apply row records which of the two lanes was written
256		 * as its `mode` — `materialized` or `changeset-lane`.
257		 */
258		materialize: boolean;
259		dryRun: boolean;
260		ingest: IngestDeclarations;
261		licence: LicencePolicy;
262		eraCell: EraCellDeclarations;
263		angular: Readonly<{
264			sourceDirectories?: readonly string[] | undefined;
265			templateDirectories?: readonly string[] | undefined;
266			styleSheetDirectories?: readonly string[] | undefined;
267			/**
268			 * The `--cell` declaration, as an identifier, for the plan stage to
269			 * resolve. It is not resolved here: an identifier no frozen adapter
270			 * publishes is the plan stage's refusal, and the run record has to be
271			 * able to attribute it to the plan row rather than to the chaining.
272			 */
273			cellId?: string | null | undefined;
274		}>;
275		react: Readonly<{ entryModule?: string | undefined }>;
276		install: InstallPolicy;
277		/** The flags this command line carried, for the forwarding table. */
278		flags: Readonly<Record<string, readonly string[]>>;
279	}>;
280	
281	/** Why the stages after the one that stopped the run were not reached. */
282	function notRunBecause(stage: RunStageName, status: 'refused' | 'defect'): string {
283		return `not-run-because: ${stage} ${status === 'refused' ? 'refused' : 'raised a defect'}`;
284	}
285	
286	type RunState = {
287		readonly rows: RunStageRow[];
288		/** The stage that stopped the run, once one has. */
289		halted: Readonly<{ stage: RunStageName; status: 'refused' | 'defect' }> | null;
290		refusal: PipelineRefusal | null;
291		defect: Readonly<{ stage: RunStageName; message: string }> | null;
292	};
293	
294	/**
295	 * The stage seam: the one place a stage begins and ends.
296	 *
297	 * Everything a reader can say per stage is decided here — when it started,
298	 * when it ended, whether it ran, and what it refused with. A stage after the
299	 * run has halted is recorded rather than skipped silently, because a table
300	 * missing its later rows reads as a run that was never asked for them.
301	 */
302	async function runStage<T>(
303		state: RunState,
304		name: RunStageName,
305		stage: () => Promise<T>,
306	): Promise<T | null> {
307		const halted = state.halted;
308		if (halted !== null) {
309			const at = new Date().toISOString();
310			state.rows.push(
311				Object.freeze({
312					name,
313					status: 'not-run' as const,
314					reason: notRunBecause(halted.stage, halted.status),
315					startedAt: at,
316					endedAt: at,
317				}),
318			);
319			return null;
320		}
321		const startedAt = new Date().toISOString();
322		try {
323			const value = await stage();
324			state.rows.push(
325				Object.freeze({
326					name,
327					status: 'ran' as const,
328					record: value,
329					startedAt,
330					endedAt: new Date().toISOString(),
331				}),
332			);
333			return value;
334		} catch (error) {
335			const endedAt = new Date().toISOString();
336			const refusal = pipelineRefusalOf(error);
337			if (refusal !== null) {
338				state.rows.push(
339					Object.freeze({
340						name,
341						status: 'refused' as const,
342						reason: refusal.code,
343						refusal,
344						startedAt,
345						endedAt,
346					}),
347				);
348				state.halted = Object.freeze({ stage: name, status: 'refused' as const });
349				state.refusal = refusal;
350				return null;
351			}
352			/**
353			 * A defect is carried rather than rethrown, and it is carried here for
354			 * the same reason a refusal is: the stage table is the outcome a reader
355			 * needs, and an exception that escapes this seam takes the table with
356			 * it. The exit code is still 1 and the stage is still named, so nothing
357			 * a defect used to be scored as has changed.
358			 */
359			const message = error instanceof Error ? error.message : String(error);
360			state.rows.push(
361				Object.freeze({ name, status: 'defect' as const, reason: message, startedAt, endedAt }),
362			);
363			state.halted = Object.freeze({ stage: name, status: 'defect' as const });
364			state.defect = Object.freeze({ stage: name, message });
365			return null;
366		}
367	}
368	
369	/** The stage order with the declarations each stage is handed, and nothing run. */
370	export function runStagePlan(
371		flags: Readonly<Record<string, readonly string[]>>,
372	): readonly RunStagePlanRow[] {
373		return Object.freeze(
374			RUN_STAGES.map((name) =>
375				Object.freeze({
376					name,
377					forwards: Object.freeze(
378						RUN_STAGE_FLAGS[name].filter((flag) => flags[flag] !== undefined),
379					),
380				}),
381			),
382		);
383	}
384	
385	/**
386	 * Run all nine stages, or state which one stopped the run.
387	 *
388	 * The stages are composed here in order and nowhere else. Each one receives
389	 * the declarations its own command would give it, which is what makes the
390	 * refusing defaults survive the chain: nothing is widened on the way through.
391	 */
392	export async function runFullPipeline(declarations: RunDeclarations): Promise<RunRecord> {
393		const stagePlan = runStagePlan(declarations.flags);
394		const application = displayPath(declarations.appRoot);
395		const lane = displayPath(declarations.out);
396		const report = await readCoverageReportSlot();
397		/**
398		 * The frontend reading is made once, before the stages, and every stage that
399		 * composes is given it. It cannot be taken off the ingest record because
400		 * `analyze` runs first, and it is not re-read per stage because two readings
401		 * of the same tree that disagree would be a defect nobody could see. When
402		 * the reading refuses, this stays at the app root and the `ingest` stage
403		 * raises the same refusal in the row that owns it.
404		 */
405		let frontend: RunRecord['roots'] = Object.freeze({
406			source: displayPath(declarations.sourceRoot),
407			frontend: displayPath(declarations.appRoot),
408			frontendSource: 'not-read' as const,
409			frontendBasis:
410				'the frontend root reading refused; the ingest stage below states which refusal.',
411		});
412		let composeRoot = declarations.appRoot;
413		try {
414			const reading = await readFrontendRoot(
415				declarations.sourceRoot,
416				declarations.ingest.frontendRoot,
417			);
418			/**
419			 * An operator who declared `--source-root` separately from the
420			 * application root has already said which directory the application is.
421			 * The reading is recorded either way; it replaces the composition root
422			 * only when one root was named and the pipeline had to find the
423			 * frontend inside it.
424			 */
425			if (path.resolve(declarations.appRoot) === path.resolve(declarations.sourceRoot))
426				composeRoot = path.join(declarations.sourceRoot, reading.frontendRoot);
427			frontend = Object.freeze({
428				source: displayPath(declarations.sourceRoot),
429				frontend: displayPath(composeRoot),
430				frontendSource: reading.frontendRootSource,
431				frontendBasis: reading.frontendRootBasis,
432			});
433		} catch (error) {
434			if (pipelineRefusalOf(error) === null) throw error;
435		}
436		if (declarations.dryRun)
437			return Object.freeze({
438				schema: RUN_SCHEMA,
439				flow: 'run' as const,
440				outcome: 'not-run' as const,
441				exitCode: EXIT_PROCEEDED,
442				application,
443				lane,
444				roots: frontend,
445				dryRun: true,
446				stagePlan,
447				stages: Object.freeze([]),
448				report,
449				notEstablished: Object.freeze([
450					'--dry-run was declared, so no stage ran. Nothing here establishes what any of them would have recorded, and nothing was written into the lane.',
451					...RUN_NOT_ESTABLISHED,
452					REPORT_NOT_ESTABLISHED[report.status],
453				]),
454			});
455		const state: RunState = { rows: [], halted: null, refusal: null, defect: null };
456		const analysis = await runStage(state, 'analyze', () => analyzeApplication(composeRoot));
457		await runStage(state, 'ingest', () =>
458			ingestApplicationSource(declarations.sourceRoot, declarations.ingest),
459		);
460		await runStage(state, 'license-at-pin', async () => {
461			const manifest = path.join(composeRoot, 'package.json');
462			return readLicenceAtPin(
463				declarations.sourceRoot,
464				(await fileExists(manifest)) ? manifest : null,
465				declarations.licence,
466			);
467		});
468		/**
469		 * The era-cell record is held, not discarded.
470		 *
471		 * That stage's own `notEstablished` states that *"the runtime named here is
472		 * the runtime the lane this pipeline composes will be installed and built
473		 * in"*, and until this variable existed the record was written into the
474		 * stage table and dropped: `PATH` reached the install child verbatim, so a
475		 * lane whose cell provisioned Node 16 had its closure resolved by whatever
476		 * Node the operator invoked this pipeline with. The claim is now carried to
477		 * the two stages it is about, and recorded on both of their rows.
478		 */
479		const cell = await runStage(state, 'era-cell', () =>
480			establishEraCell(composeRoot, declarations.eraCell),
481		);
482		const runtime = await planLaneRuntime(cell?.provision ?? null);
483		const planned = await runStage(state, 'plan', () =>
484			planApplication({
485				appRoot: composeRoot,
486				angular: declarations.angular,
487				react: declarations.react,
488			}),
489		);
490		const applied = await runStage(state, 'apply', async () => {
491			if (planned === null || analysis === null)
492				throw new Error(
493					'run: the apply stage was reached without a plan. This is a defect in the chaining rather than a refusal: the stage order guarantees a plan before an apply.',
494				);
495			const changeset = await applyPlan(planned.plan, {
496				appRoot: composeRoot,
497				out: declarations.out,
498				materialize: declarations.materialize,
499			});
500			const composition = await composeLane(
501				composeRoot,
502				declarations.out,
503				planned.plan.lineage,
504				analysis.builder,
505			);
506			await writeLaneFiles(declarations.out, composition);
507			return {
508				applied: changeset,
509				laneComposition: {
510					...composition,
511					files: composition.files.map(({ source: _source, ...rest }) => rest),
512				},
513			};
514		});
515		await runStage(state, 'install', () =>
516			runLaneInstall(
517				declarations.out,
518				declarations.install,
519				process.env,
520				applied?.laneComposition.composed === true ? 'resolve' : 'replay',
521				process.cwd(),
522				runtime,
523			),
524		);
525		const built = await runStage(state, 'build', () =>
526			runLaneBuild(declarations.out, undefined, process.env, runtime),
527		);
528		await runStage(state, 'witness', () =>
529			runLaneWitness({
530				application: path.basename(declarations.appRoot),
531				sourceRoot: declarations.appRoot,
532				laneBuild: path.join(declarations.out, built?.outDirectory ?? 'dist'),
533			}),
534		);
535		const halted = state.halted;
536		const exitCode =
537			halted === null ? EXIT_PROCEEDED : halted.status === 'refused' ? EXIT_REFUSAL : EXIT_DEFECT;
538		return Object.freeze({
539			schema: RUN_SCHEMA,
540			flow: 'run' as const,
541			outcome:
542				halted === null
543					? ('proceeded' as const)
544					: halted.status === 'refused'
545						? ('refused' as const)
546						: ('defect' as const),
547			exitCode,
548			application,
549			lane,
550			roots: frontend,
551			dryRun: false,
552			stagePlan,
553			stages: Object.freeze([...state.rows]),
554			...(state.refusal === null ? {} : { refusal: state.refusal }),
555			...(state.defect === null ? {} : { defect: state.defect }),
556			report,
557			notEstablished: Object.freeze([
558				...RUN_NOT_ESTABLISHED,
559				REPORT_NOT_ESTABLISHED[report.status],
560			]),
561		});
562	}
563	
564	const STAGE_COLUMN = Math.max(...RUN_STAGES.map((name) => name.length)) + 2;
565	
566	function renderStagePlan(plan: readonly RunStagePlanRow[]): readonly string[] {
567		return plan.map(
568			(row, index) =>
569				`  ${String(index + 1)}. ${row.name.padEnd(STAGE_COLUMN)}${
570					row.forwards.length === 0
571						? 'no declaration from this command line'
572						: row.forwards.join(' ')
573				}`,
574		);
575	}
576	
577	/** The run as an operator reads it: the stage table, then whatever stopped it. */
578	export function renderRun(record: RunRecord): string {
579		const lines = [
580			`application: ${record.application}`,
581			`lane: ${record.lane}`,
582			`acquisition root: ${record.roots.source}`,
583			`frontend root: ${record.roots.frontend} (${record.roots.frontendSource})`,
584			`frontend root basis: ${record.roots.frontendBasis}`,
585			'',
586		];
587		if (record.dryRun) {
588			lines.push('dry run: the stage order and the declarations each stage would be given.');
589			lines.push('');
590			lines.push(...renderStagePlan(record.stagePlan));
591			lines.push('');
592			lines.push('No stage ran and nothing was written into the lane.');
593		} else {
594			for (const row of record.stages)
595				lines.push(
596					`  ${row.name.padEnd(STAGE_COLUMN)}${row.status.padEnd(10)}${row.reason ?? ''}`,
597				);
598			lines.push('');
599			lines.push(
600				record.outcome === 'proceeded'
601					? `all ${String(record.stages.length)} stage(s) proceeded.`
602					: record.outcome === 'refused'
603						? `stopped at ${record.refusal?.stage ?? ''}.`
604						: `stopped at ${record.defect?.stage ?? ''} with a defect.`,
605			);
606		}
607		lines.push('');
608		if (record.refusal !== undefined) lines.push(renderRefusal(record.refusal));
609		if (record.defect !== undefined) {
610			lines.push(`defect: ${record.defect.stage}`);
611			lines.push('');
612			lines.push(record.defect.message);
613			lines.push('');
614		}
615		lines.push(
616			record.report.status === 'emitted'
617				? `report: emitted at ${record.report.path} (${record.report.digest})`
618				: `report: ${record.report.status} (${record.report.slot}) — ${record.report.reason}`,
619		);
620		lines.push('');
621		for (const line of record.notEstablished) lines.push(`not established: ${line}`);
622		return `${lines.join('\n')}\n`;
623	}
