1	/**
2	 * The `build` stage: run the lane's own build script against the lane's own
3	 * generated configuration.
4	 *
5	 * The build path for the applications already completed is not in the operator
6	 * flow at all — `packages/cli/src/fixture/react-hospitalrun-vite8-run.ts` runs
7	 * the *workspace's* Vite binary against a *workspace* configuration file, and
8	 * that file imports the frozen adapter by source path. The lane is never
9	 * self-contained in that arrangement, and nothing an operator can run
10	 * reproduces it.
11	 *
12	 * This stage runs the script the lane's own rewritten manifest declares, from
13	 * the lane, resolving the build tool out of the lane's own installed closure.
14	 * The one thing the lane still reaches into this workspace for is the frozen
15	 * adapter source, exactly as the fixture configurations do. Making the lane
16	 * resolve a published `@versionless/react` instead is a packaging decision this
17	 * stage deliberately does not take, and the record says so rather than leaving
18	 * a reader to discover it from the import specifier.
19	 *
20	 * Two lane kinds are recognised, and the lane on disk chooses between them
21	 * rather than a declaration this stage was handed: a lane carrying an
22	 * `angular.json` is built by whatever its own build script tells the Angular
23	 * CLI to do, and a lane carrying the generated Vite configuration is built by
24	 * Vite. Neither command is composed here. A lane that is neither is refused by
25	 * a name that says so, instead of being told it carries no `vite.config.ts` —
26	 * that sentence described this stage's expectation rather than the lane's
27	 * condition, and it is now reserved for the lane it is true of.
28	 *
29	 * A non-zero exit from the build is a **defect**, not a refusal.
30	 */
31	
32	import { execFile } from 'node:child_process';
33	import { readdir } from 'node:fs/promises';
34	import { promisify } from 'node:util';
35	import * as path from 'pathe';
36	import { directoryExists, readJsonFile } from './analyze.ts';
37	import {
38		INHERITED_LANE_RUNTIME,
39		laneRuntimeEnvironment,
40		readLaneRuntime,
41		type LaneRuntime,
42		type LaneRuntimePlan,
43	} from './install.ts';
44	import { LANE_BUILD_DIRECTORY } from './lane.ts';
45	import { refuse } from './refusals.ts';
46	
47	const run = promisify(execFile);
48	
49	const BUILD_NOT_ESTABLISHED: readonly string[] = Object.freeze([
50		'A completed build establishes that the lane emitted output. It is not a browser proof, a parity reading, or a witness pass; nothing here establishes that the emitted bundle behaves as the application did on its era toolchain.',
51		'The lane resolves the frozen adapter from this workspace by relative path, so this build is reproducible by this pipeline in this checkout. It does not establish that the lane builds anywhere else.',
52		'`outputFiles` counts files below the build directory. It is a count, not a comparison against any previous build.',
53	]);
54	
55	export type BuildPlan = Readonly<{
56		command: readonly string[];
57		script: string;
58		configuration: string;
59		/** Where the identified lane says its build lands, relative to the lane. */
60		outDirectory: string;
61	}>;
62	
63	/**
64	 * Decide the build command for a lane and read where its output lands, or
65	 * refuse by name.
66	 *
67	 * `outDirectory` is a reading taken from the lane the gates just identified,
68	 * not a property of this stage. Two lane kinds are recognised and each answers
69	 * for itself: a Vite lane answers with the constant its own generated
70	 * configuration was written with, an Angular lane answers with the
71	 * `outputPath` its own workspace declares. The field carries whatever the
72	 * recognised lane answers.
73	 *
74	 * The first two gates are lineage-independent — a lane with no closure and a
75	 * lane with no build script are the same fact whatever built it — so they run
76	 * before the lane kind is asked for at all, exactly as they did.
77	 */
78	export async function planLaneBuild(
79		laneDir: string,
80		configuration = 'vite.config.ts',
81	): Promise<BuildPlan> {
82		if (!(await directoryExists(path.join(laneDir, 'node_modules'))))
83			refuse({
84				code: 'build.lane-closure-absent',
85				message:
86					'Build: the lane carries no node_modules, so the build tool its manifest declares is not resolvable from the lane. Run the install stage first rather than have this stage build against the workspace closure instead of the lane closure.',
87				stage: 'build',
88				origin: 'pipeline',
89			});
90		const manifest = await readJsonFile(path.join(laneDir, 'package.json'));
91		const scripts = (manifest?.scripts ?? {}) as Record<string, string>;
92		const script = scripts.build;
93		if (typeof script !== 'string' || script.trim() === '')
94			refuse({
95				code: 'build.no-build-script',
96				message:
97					"Build: the lane's package.json declares no build script, so there is no command to run. The lane composition rewrites that script; a lane without one was not composed by this flow.",
98				stage: 'build',
99				origin: 'pipeline',
100			});
101		const kind = await laneBuildKind(laneDir, configuration, script);
102		if (kind === null)
103			refuse({
104				code: 'build.lane-kind-unrecognised',
105				message: `Build: the lane carries an installed closure and the build script \`${script}\`, but neither an ${ANGULAR_WORKSPACE_FILE} nor a ${configuration}, so this stage holds no build contract for it. It declines to run an unrecognised lane's script rather than run it and then count files below a directory no lane declared.`,
106				stage: 'build',
107				origin: 'pipeline',
108			});
109		if (kind === 'angular') return angularLaneBuildPlan(laneDir, script, scripts);
110		const outDirectory = await viteLaneOutDirectory(laneDir, configuration);
111		return Object.freeze({
112			command: Object.freeze(['npm', 'run', 'build']),
113			script,
114			configuration,
115			outDirectory,
116		});
117	}
118	
119	/** The build contracts this stage holds. A lane answers to one of them or none. */
120	type LaneBuildKind = 'angular' | 'vite';
121	
122	/**
123	 * Which build contract the lane answers to, read off the lane rather than
124	 * declared to this stage.
125	 *
126	 * `run` passes this stage a lane, an environment and a runtime and nothing
127	 * else, so the lineage the analyze stage read is not available
128	 * here and the lane itself has to say what it is. An `angular.json` at the lane
129	 * root is the Angular workspace's own declaration of itself and is asked for
130	 * first; a lane that carries the generated Vite configuration is the Vite lane
131	 * this stage has always built.
132	 *
133	 * The third question is what keeps `build.configuration-absent` meaning
134	 * something. A lane whose build script invokes `vite` and which carries no
135	 * configuration is a Vite lane with its configuration missing — that is the
136	 * fact that refusal names — while a lane that answers neither question is not
137	 * a Vite lane at all and is owed a different sentence.
138	 */
139	async function laneBuildKind(
140		laneDir: string,
141		configuration: string,
142		script: string,
143	): Promise<LaneBuildKind | null> {
144		if (await fileInLane(laneDir, ANGULAR_WORKSPACE_FILE)) return 'angular';
145		if (await fileInLane(laneDir, configuration)) return 'vite';
146		return INVOKES_VITE.test(script) ? 'vite' : null;
147	}
148	
149	/**
150	 * Where a Vite lane's build lands, asked of the lane rather than assumed of
151	 * every lane.
152	 *
153	 * The plan used to write `LANE_BUILD_DIRECTORY` in directly, which was true of
154	 * the only lane this stage can build and said nothing about the lane itself. It
155	 * is a reading now: the lane is identified by the configuration it carries, and
156	 * that identification is what answers where the output goes. The answer for a
157	 * Vite lane is still the constant, and deliberately so — `lane.ts:486` wrote
158	 * that same constant into the generated configuration this gate just found, so
159	 * reading the lane and reading the constant are one fact. It is imported rather
160	 * than repeated here so the two cannot drift apart.
161	 */
162	async function viteLaneOutDirectory(laneDir: string, configuration: string): Promise<string> {
163		if (!(await fileInLane(laneDir, configuration)))
164			refuse({
165				code: 'build.configuration-absent',
166				message: `Build: the lane carries no ${configuration}, so the generated build configuration this stage runs against is missing. The lane composition writes it; a lane without one was not composed by this flow.`,
167				stage: 'build',
168				origin: 'pipeline',
169			});
170		return LANE_BUILD_DIRECTORY;
171	}
172	
173	/** The file an Angular workspace declares itself in, at the lane root. */
174	const ANGULAR_WORKSPACE_FILE = 'angular.json';
175	
176	/**
177	 * A script that invokes the Angular CLI's build, in either spelling this
178	 * repository has evidence of: the bare `ng build` angular2-hn's manifest
179	 * declares, and the `…/@angular/cli/bin/ng.js build` form pigallery2's probe
180	 * ran. `ng-build` and `packaging build` are not it.
181	 */
182	const INVOKES_NG_BUILD = /(?:^|[\s;&|(]|[./])ng(?:\.js)?\s+build(?![\w-])/;
183	
184	/** A script that invokes Vite. `vitest` is not it. */
185	const INVOKES_VITE = /(?:^|[\s;&|(]|[./])vite(?![\w-])/;
186	
187	/**
188	 * The plan for a lane that declares an Angular workspace.
189	 *
190	 * Two things are read off the lane and nothing is composed. The command is
191	 * `npm run build` — the same command the Vite lane gets — because the honest
192	 * builder of an Angular application is the application's own script: the green
193	 * precedent in this repository is eshop-webspa, whose production build ran
194	 * `build:prod`, and whose era flag spellings (`--prod --aot --extract-css`)
195	 * were translated by the frozen adapter rather than composed by a pipeline
196	 * (`packages/frameworks/angular/src/workspace-script-flags.ts`). A stage that
197	 * wrote `ng build --configuration production` in here would be stepping over
198	 * that translation seam and disagreeing with every lane whose script says
199	 * something else.
200	 *
201	 * The output directory is the workspace's own `outputPath`. It is why this
202	 * branch exists at all: angular2-hn declares `dist/angular-hnpwa`, and the
203	 * constant a Vite lane answers with would have counted files below a directory
204	 * the Angular build never writes.
205	 *
206	 * What this plan does **not** establish: that `npm run build` selects the
207	 * production configuration. angular2-hn's script is bare `ng build` and its
208	 * build target declares no `defaultConfiguration`, so the CLI takes base
209	 * options — no `fileReplacements`, no `outputHashing`, no budgets. That is the
210	 * lane's declaration, reported by running it, not a choice made here.
211	 */
212	async function angularLaneBuildPlan(
213		laneDir: string,
214		script: string,
215		scripts: Record<string, string>,
216	): Promise<BuildPlan> {
217		if (!INVOKES_NG_BUILD.test(script))
218			refuse({
219				code: 'build.no-ng-build-script',
220				message: `Build: the lane declares an ${ANGULAR_WORKSPACE_FILE}, so its build is the one its own Angular CLI script runs, but its build script is \`${script}\` and nothing in it invokes \`ng build\`. ${otherNgBuildScripts(scripts)} This stage runs the lane's build script and composes no \`ng\` command of its own, so it refuses rather than run a script that will not build this workspace.`,
221				stage: 'build',
222				origin: 'pipeline',
223			});
224		return Object.freeze({
225			command: Object.freeze(['npm', 'run', 'build']),
226			script,
227			configuration: ANGULAR_WORKSPACE_FILE,
228			outDirectory: angularLaneOutDirectory(
229				await readJsonFile(path.join(laneDir, ANGULAR_WORKSPACE_FILE)),
230			),
231		});
232	}
233	
234	/** Which other scripts invoke `ng build`, for a manifest whose `build` does not. */
235	function otherNgBuildScripts(scripts: Record<string, string>): string {
236		const invoking = Object.entries(scripts)
237			.filter(([name, value]) => name !== 'build' && INVOKES_NG_BUILD.test(String(value)))
238			.map(([name]) => name);
239		return invoking.length === 0
240			? 'No other script in this manifest invokes it either.'
241			: `The scripts that do invoke it are ${invoking.join(', ')}; this stage runs \`npm run build\` and does not choose among them.`;
242	}
243	
244	/**
245	 * Where an Angular lane's build lands: the `outputPath` the one project with a
246	 * build target declares, read off the workspace the lane carries.
247	 *
248	 * A single-project workspace is the whole population this stage has evidence
249	 * of — angular2-hn declares one project, eshop-webspa declares one — and a
250	 * workspace with two buildable projects is a question nobody answered: `run`
251	 * carries no project declaration, so choosing one would be a guess about which
252	 * application the lane is. The empty case, the unreadable case and the
253	 * ambiguous case are one refusal, because they mean one thing: this stage
254	 * cannot name a single build target. The message says which of the three it
255	 * was, so the refusal is countable without being vague.
256	 *
257	 * `architect` and `targets` are the two spellings of the same slot in the
258	 * workspace schema, so both are read rather than one being preferred.
259	 */
260	function angularLaneOutDirectory(workspace: Record<string, unknown> | null): string {
261		const projects = objectOf(workspace?.projects);
262		const declared = Object.entries(projects)
263			.map(([name, project]) => ({ name, target: buildTargetOf(project) }))
264			.filter(
265				(entry): entry is { name: string; target: Record<string, unknown> } =>
266					entry.target !== null,
267			);
268		if (declared.length !== 1)
269			refuse({
270				code: 'build.workspace-target-absent',
271				message: `Build: the lane's ${ANGULAR_WORKSPACE_FILE} ${
272					workspace === null
273						? 'does not read as a JSON object, so no project in it can be read'
274						: declared.length === 0
275							? `declares no project with a build target (projects declared: ${Object.keys(projects).join(', ') || 'none'})`
276							: `declares a build target for more than one project (${declared.map((entry) => entry.name).join(', ')}), and this run names no project to build`
277				}, so this stage has no single build target to read the output directory from. It refuses rather than build one project and record it as the lane's.`,
278				stage: 'build',
279				origin: 'pipeline',
280			});
281		const [only] = declared as [{ name: string; target: Record<string, unknown> }];
282		const outputPath = objectOf(only.target.options).outputPath;
283		if (typeof outputPath !== 'string' || outputPath.trim() === '')
284			refuse({
285				code: 'build.output-path-absent',
286				message: `Build: the build target of project ${only.name} in the lane's ${ANGULAR_WORKSPACE_FILE} declares no \`options.outputPath\` this stage can read as a path, so where its build lands is unknown. This stage counts the files a build emitted below the directory the lane declared; it will not assume one.`,
287				stage: 'build',
288				origin: 'pipeline',
289			});
290		return outputPath;
291	}
292	
293	/** The `build` target a workspace project declares, in either spelling, or null. */
294	function buildTargetOf(project: unknown): Record<string, unknown> | null {
295		const declared = objectOf(project);
296		const targets = objectOf(declared.architect ?? declared.targets);
297		const build = targets.build;
298		return build !== null && typeof build === 'object' && !Array.isArray(build)
299			? (build as Record<string, unknown>)
300			: null;
301	}
302	
303	/** A reading as the record it is, or an empty one for anything that is not one. */
304	function objectOf(value: unknown): Record<string, unknown> {
305		return value !== null && typeof value === 'object' && !Array.isArray(value)
306			? (value as Record<string, unknown>)
307			: {};
308	}
309	
310	async function fileInLane(laneDir: string, file: string): Promise<boolean> {
311		try {
312			return (await readdir(laneDir)).includes(file);
313		} catch {
314			return false;
315		}
316	}
317	
318	async function countFilesBelow(directory: string): Promise<number> {
319		if (!(await directoryExists(directory))) return 0;
320		let count = 0;
321		for (const entry of await readdir(directory, { withFileTypes: true })) {
322			if (entry.isDirectory()) {
323				count += await countFilesBelow(path.join(directory, entry.name));
324				continue;
325			}
326			if (entry.isFile()) count += 1;
327		}
328		return count;
329	}
330	
331	export type BuildRecord = Readonly<{
332		stage: 'build';
333		ran: boolean;
334		reason: string | null;
335		command: readonly string[] | null;
336		script: string | null;
337		configuration: string | null;
338		outDirectory: string | null;
339		exitCode: number | null;
340		outputFiles: number | null;
341		/** The Node runtime the build child resolved, and where it came from. */
342		runtime: LaneRuntime | null;
343		notEstablished: readonly string[];
344	}>;
345	
346	/** The record for a stage the run did not ask for. */
347	export function buildNotRequested(reason: string): BuildRecord {
348		return Object.freeze({
349			stage: 'build',
350			ran: false,
351			reason,
352			command: null,
353			script: null,
354			configuration: null,
355			outDirectory: null,
356			exitCode: null,
357			outputFiles: null,
358			runtime: null,
359			notEstablished: BUILD_NOT_ESTABLISHED,
360		});
361	}
362	
363	/**
364	 * Run the build this stage planned. A non-zero exit is a defect.
365	 *
366	 * `runtime` is the era-cell stage's provision, carried this far so the build
367	 * child runs in the runtime that stage named instead of in whatever the
368	 * invoking `PATH` happens to hold. It matters most where it is least visible:
369	 * the Angular CLI 13 this repository's Angular lanes carry warns and proceeds
370	 * on an even Node major above 16 rather than refusing it, so a build under the
371	 * wrong runtime does not fail at the CLI — it fails somewhere inside webpack
372	 * with a diagnostic that names neither Node nor the cell.
373	 */
374	export async function runLaneBuild(
375		laneDir: string,
376		configuration = 'vite.config.ts',
377		environment: NodeJS.ProcessEnv = process.env,
378		runtime: LaneRuntimePlan = INHERITED_LANE_RUNTIME,
379	): Promise<BuildRecord> {
380		const plan = await planLaneBuild(laneDir, configuration);
381		const inherited = laneRuntimeEnvironment(runtime, environment);
382		const [binary, ...args] = plan.command as readonly [string, ...string[]];
383		try {
384			await run(binary, args, { cwd: laneDir, env: inherited, maxBuffer: 64 * 1024 * 1024 });
385		} catch (error) {
386			const detail = error instanceof Error ? error.message : String(error);
387			throw new Error(
388				`build: ${plan.command.join(' ')} failed in the lane. This is a defect rather than a refusal: the lane was composed and installed and the build still did not complete. ${detail}`,
389			);
390		}
391		return Object.freeze({
392			stage: 'build',
393			ran: true,
394			reason: null,
395			command: plan.command,
396			script: plan.script,
397			configuration: plan.configuration,
398			outDirectory: plan.outDirectory,
399			exitCode: 0,
400			outputFiles: await countFilesBelow(path.join(laneDir, plan.outDirectory)),
401			runtime: await readLaneRuntime(runtime, inherited),
402			notEstablished: BUILD_NOT_ESTABLISHED,
403		});
404	}
