247		lockfile: string | null;
248		closure: ClosureMode;
249		/** What was read out of the lockfile, or `null` when none was read. */
250		findings: LockfileFindings | null;
251		policy: InstallPolicy;
252		/** The foreign lockfile a declared policy disregarded, or `null`. */
253		foreignLockfileDisregarded: ForeignLockfileDisregard | null;
254		command: readonly string[];
255	}>;
