257	/**
258	 * Decide the install command for a lane, or refuse by name.
259	 *
260	 * Nothing runs here. The whole point is that every decision this stage would
261	 * otherwise ask an operator for is taken from the declared policy and the
262	 * lockfile before a registry is contacted.
263	 */
264	export async function planLaneInstall(
265		laneDir: string,
266		policy: InstallPolicy = DEFAULT_INSTALL_POLICY,
267		environment: NodeJS.ProcessEnv = process.env,
268		closure: ClosureMode = 'replay',
269	): Promise<InstallPlan> {
270		if (policy.allowInstallScripts && policy.skipInstallScripts)
271			refuse({
272				code: 'install.install-script-policy-conflicts',
273				message:
274					'Install: the install-script allowance and the install-script skip were both declared. They are opposite policies and this flow does not pick between two declarations.',
275				stage: 'install',
276				origin: 'pipeline',
277			});
278		if (environment.VERSIONLESS_NETWORK_MODE === 'offline')
279			refuse({
280				code: 'install.network-not-permitted',
281				message:
282					'Install: VERSIONLESS_NETWORK_MODE is offline, so this stage may not reach a registry. No closure was resolved and nothing was installed.',
283				stage: 'install',
284				origin: 'pipeline',
285			});
286		/**
287		 * Which lockfiles the lane actually carries, read before anything is said
288		 * about them. The order matters, and it is the order a reader would want:
289		 * an npm lockfile is looked for first, so that "there is nothing to install
290		 * from" is only ever said about a lane where that is true.
291		 */
292		let lockfile: string | null = null;
293		for (const name of NPM_LOCKFILES)
294			if (lockfile === null && (await fileExists(path.join(laneDir, name)))) lockfile = name;
295		const foreign: string[] = [];
296		for (const name of Object.keys(FOREIGN_LOCKFILES).sort())
297			if (await fileExists(path.join(laneDir, name))) foreign.push(name);
298		/**
299		 * A lane pinned by another package manager *as well as* by npm. Both are
300		 * present, so this is not a lane missing a closure — it is a lane carrying
301		 * two, and the policies this stage holds are npm's.
302		 */
303		if (lockfile !== null && foreign.length > 0) {
304			const name = foreign[0] as string;
305			refuse({
306				code: 'install.package-manager-not-npm',
307				message: `Install: the lane carries ${name}, so its closure is pinned by ${FOREIGN_LOCKFILES[name] ?? 'another package manager'}. The two policies this stage carries — the remote-tarball allowance and the install-script allowance — are npm policies, and this flow does not translate them onto another package manager.`,
308				stage: 'install',
309				origin: 'pipeline',
310			});
311		}
312		/**
313		 * A lockfile is present and this stage does not read it.
314		 *
315		 * Undeclared this is a refusal, and saying `absent` here would be false: the
316		 * application pinned its closure, it pinned it with a package manager whose
317		 * lockfile this stage cannot read, and those are different findings for an
318		 * operator deciding what to do next.
319		 *
320		 * `--allow-foreign-lockfile` is the declaration that answers it, and what it
321		 * declares is *not* that the foreign lockfile is readable after all — it is
322		 * that this lane may be installed without any pin at all. The foreign file is
323		 * left exactly where it is and is never opened; npm resolves the closure
324		 * fresh from the manifest. The drift that buys is recorded on the row rather
325		 * than swallowed, and the policy is only ever taken because an operator
326		 * declared it: nothing here infers it from the lockfile kind.
327		 */
328		let disregarded: ForeignLockfileDisregard | null = null;
329		if (lockfile === null) {
330			if (foreign.length > 0) {
331				if (!policy.allowForeignLockfile)
332					refuse({
333						code: 'install.lockfile-foreign',
334						message: `Install: the lane carries ${foreign.join(', ')}, and this stage reads ${NPM_LOCKFILES.join(', ')}. The closure is pinned — by ${FOREIGN_LOCKFILES[foreign[0] as string] ?? 'another package manager'} — and it is pinned in a lockfile this flow does not read, so it is not absent and it is not installable here.`,
335						stage: 'install',
336						origin: 'pipeline',
337					});
338				disregarded = foreignLockfileDisregard(foreign);
339			} else
340				refuse({
341					code: 'install.lockfile-absent',
342					message: `Install: the lane carries none of ${NPM_LOCKFILES.join(', ')}, so there is no pinned closure to install. This flow installs a recorded closure rather than resolving a new one.`,
343					stage: 'install',
344					origin: 'pipeline',
345				});
346		}
347		/**
348		 * The policy findings, when there is a lockfile to read them out of. With
349		 * the foreign-lockfile policy taken there is none, and the two gates below
350		 * are not silently satisfied — they are recorded as never having run, on the
351		 * row itself.
352		 */
353		let findings: LockfileFindings | null = null;
354		if (lockfile !== null) {
355			const document = await readJsonFile(path.join(laneDir, lockfile));
356			if (document === null)
357				refuse({
358					code: 'install.lockfile-unreadable',
359					message: `Install: ${lockfile} is not readable as a JSON object, so the closure it pins cannot be read and no install policy can be checked against it.`,
360					stage: 'install',
361					origin: 'pipeline',
362				});
363			findings = readLockfileFindings(lockfile, document);
364			if (findings.remoteTarballDependencies.length > 0 && !policy.allowRemoteTarballs)
365				refuse({
366					code: 'install.remote-tarball-policy-not-declared',
367					message: `Install: the lockfile resolves ${String(findings.remoteTarballDependencies.length)} dependency(ies) from outside ${DEFAULT_REGISTRY_HOST}, first ${findings.remoteTarballDependencies[0] ?? ''}. Modern npm refuses those with EALLOWREMOTE unless the remote-tarball allowance is declared. Declare --allow-remote-tarballs to carry that policy; this flow does not take the allowance on an operator's behalf.`,
368					stage: 'install',
369					origin: 'pipeline',
370				});
371			if (
372				findings.installScriptPackages.length > 0 &&
373				!policy.allowInstallScripts &&
374				!policy.skipInstallScripts
375			)
376				refuse({
377					code: 'install.install-script-policy-not-declared',
378					message: `Install: the lockfile declares ${String(findings.installScriptPackages.length)} package(s) carrying an install script, first ${findings.installScriptPackages[0] ?? ''}. Modern npm skips them by default, which produces a tree whose native build was never attempted. Declare --allow-install-scripts to run them or --skip-install-scripts to record the skip as a decision; this flow does not let the default stand unnamed.`,
379					stage: 'install',
380					origin: 'pipeline',
381				});
382		}
383		/**
384		 * `npm ci` replays a lockfile, and there is none to replay when the policy
385		 * was taken. The mode is therefore `resolve` regardless of what the caller
386		 * asked for — recorded as `resolve`, so the row says what actually happened.
387		 */
388		const resolvedClosure: ClosureMode = disregarded === null ? closure : 'resolve';
389		const command = [
390			'npm',
391			resolvedClosure === 'replay' ? 'ci' : 'install',
392			'--no-audit',
393			'--no-fund',
394			...(policy.allowRemoteTarballs ? ['--allow-remote', 'all'] : []),
395			...(policy.allowInstallScripts ? ['--foreground-scripts'] : ['--ignore-scripts']),
396			...(policy.allowPeerConflicts ? ['--legacy-peer-deps'] : []),
397		];
398		return Object.freeze({
399			packageManager: 'npm',
400			lockfile,
401			closure: resolvedClosure,
402			findings,
403			policy,
404			foreignLockfileDisregarded: disregarded,
405			command: Object.freeze(command),
406		});
407	}
