487	export type LaneRuntime = Readonly<{
488		source: 'provisioned' | 'host';
489		cellSupplier: string | null;
490		cellVersion: string | null;
491		pathPrefix: string | null;
492		/** `node -v` read through the child's own environment, or `null`. */
493		resolvedVersion: string | null;
494		/** What this reading establishes, and what it does not. */
