511	export async function planLaneRuntime(
512		provision: Readonly<{ supplier: string; version: string; location: string }> | null,
513	): Promise<LaneRuntimePlan> {
514		if (provision === null) return INHERITED_LANE_RUNTIME;
515		const resolved = path.resolve(provision.location);
516		const prepends = await fileExists(path.join(resolved, 'bin', 'node'));
517		return Object.freeze({
518			source: prepends ? ('provisioned' as const) : ('host' as const),
