569		return Object.freeze({
570			source: plan.source,
571			cellSupplier: plan.cellSupplier,
572			cellVersion: plan.cellVersion,
573			pathPrefix: plan.pathPrefix,
574			resolvedVersion,
575			claim:
576				plan.source === 'provisioned'
