584	export type InstallSandbox = Readonly<{
585		/** The lane-owned directory handed to the child as `HOME`. */
586		home: string;
587		/** Every directory created before the child runs. */
588		directories: readonly string[];
589		/** The exact environment the child is spawned with. */
590		environment: Readonly<Record<string, string>>;
591		/** Inherited variables dropped, and why they were dropped. */
592		strippedVariables: readonly string[];
593	}>;
594	
595	/** Whether `value` names `base` or anything under it. */
596	function referencesDirectory(value: string, base: string | null): boolean {
597		if (base === null || base.length < 2) return false;
598		return value === base || value.includes(base);
599	}
