601	/**
602	 * The environment an install child gets: lane-owned, and nothing borrowed.
603	 *
604	 * Every path npm writes to outside a project — its cache, its prefix, its two
605	 * config files, and the XDG directories a package's own script reads — is
606	 * pointed inside the lane, so the ordinary case of a script writing "to the
607	 * user's config" lands in a directory the lane owns and the run can throw away.
608	 * Then every inherited variable that names the user's home or this checkout is
609	 * dropped, so a script cannot read the escape route out of its own environment.
610	 */
611	export function planInstallSandbox(
612		laneDir: string,
613		environment: NodeJS.ProcessEnv,
614		boundaryRoot: string,
615	): InstallSandbox {
616		const lane = path.resolve(laneDir);
617		const home = path.join(lane, INSTALL_HOME_DIRECTORY);
618		const config = path.join(home, '.config');
619		const cache = path.join(home, '.cache');
620		const npmCache = path.join(home, 'npm-cache');
621		const prefix = path.join(home, 'npm-prefix');
622		const owned: Record<string, string> = {
623			HOME: home,
624			XDG_CONFIG_HOME: config,
625			XDG_CACHE_HOME: cache,
626			npm_config_cache: npmCache,
627			npm_config_prefix: prefix,
628			npm_config_userconfig: path.join(home, '.npmrc'),
629			npm_config_globalconfig: path.join(prefix, 'etc', 'npmrc'),
630		};
631		const inheritedHome =
632			typeof environment.HOME === 'string' && environment.HOME !== ''
633				? path.resolve(environment.HOME)
634				: null;
635		const root = path.resolve(boundaryRoot);
636		const stripped: string[] = [];
637		const passed: Record<string, string> = {};
638		for (const key of Object.keys(environment).sort()) {
639			const value = environment[key];
640			if (value === undefined) continue;
641			if (key in owned) {
642				stripped.push(`${key} (replaced with a lane-owned directory)`);
643				continue;
644			}
645			/** npm reads its configuration from `npm_config_*` case-insensitively. */
646			if (/^npm_config_/i.test(key)) {
647				stripped.push(`${key} (inherited npm configuration)`);
648				continue;
649			}
650			if (SANDBOX_KEPT_VARIABLES.includes(key)) {
651				passed[key] = value;
652				continue;
653			}
654			if (referencesDirectory(value, inheritedHome)) {
655				stripped.push(`${key} (names the invoking user's home)`);
656				continue;
657			}
658			if (referencesDirectory(value, root)) {
659				stripped.push(`${key} (names this checkout)`);
660				continue;
661			}
662			passed[key] = value;
663		}
664		return Object.freeze({
665			home,
666			directories: Object.freeze([home, config, cache, npmCache, prefix]),
667			environment: Object.freeze({ ...passed, ...owned }),
668			strippedVariables: Object.freeze(stripped),
669		});
670	}
