683	async function hashTree(directory: string, into: Map<string, string>): Promise<void> {
684		let entries;
685		try {
686			entries = await readdir(directory, { withFileTypes: true });
687		} catch {
688			return;
689		}
690		for (const entry of entries) {
691			const full = path.join(directory, entry.name);
692			if (entry.isDirectory()) {
693				await hashTree(full, into);
694				continue;
695			}
696			if (!entry.isFile()) continue;
697			const digest = await hashIfReadable(full);
698			if (digest !== null) into.set(full, digest);
699		}
700	}
