702	/**
703	 * The surface an install child is not allowed to move, hashed.
704	 *
705	 * Two places, and both are chosen because a write there is executable rather
706	 * than merely untidy: the checkout's `.git/hooks`, which is what the husky
707	 * escape took, and the top level of the checkout, which is where a `postinstall`
708	 * that guesses at a project root lands. Neither is walked deeply, so the reading
709	 * is cheap enough to take on every install. Anything inside the lane is excluded
710	 * by construction: the lane is what the child is *for*.
711	 */
712	export async function snapshotInstallBoundary(
713		boundaryRoot: string,
714		laneDir: string,
715	): Promise<BoundarySnapshot> {
716		const root = path.resolve(boundaryRoot);
717		const lane = path.resolve(laneDir);
718		const snapshot = new Map<string, string>();
719		let entries;
720		try {
721			entries = await readdir(root, { withFileTypes: true });
722		} catch {
723			entries = [];
724		}
725		for (const entry of entries) {
726			if (!entry.isFile()) continue;
727			const digest = await hashIfReadable(path.join(root, entry.name));
728			if (digest !== null) snapshot.set(path.join(root, entry.name), digest);
729		}
730		await hashTree(path.join(root, '.git', 'hooks'), snapshot);
731		for (const file of [...snapshot.keys()])
732			if (file === lane || file.startsWith(`${lane}/`)) snapshot.delete(file);
733		return snapshot;
734	}
