736	/** Every watched path the child created, changed, or removed, named. */
737	export function boundaryWrites(
738		before: BoundarySnapshot,
739		after: BoundarySnapshot,
740		boundaryRoot: string,
741	): readonly string[] {
742		const root = path.resolve(boundaryRoot);
743		const name = (file: string): string => {
744			const relative = path.relative(root, file);
745			return relative === '' || relative.startsWith('..') ? file : relative;
746		};
747		const writes: string[] = [];
748		for (const [file, digest] of after)
749			if (before.get(file) !== digest)
750				writes.push(`${before.has(file) ? 'modified' : 'created'} ${name(file)}`);
751		for (const file of before.keys()) if (!after.has(file)) writes.push(`deleted ${name(file)}`);
752		return Object.freeze(writes.sort());
753	}
