771		foreignLockfileDisregarded: ForeignLockfileDisregard | null;
772		remoteTarballDependencies: readonly string[];
773		installScriptPackages: readonly string[];
774		command: readonly string[] | null;
775		exitCode: number | null;
776		/** Packages present in the lane's installed closure afterwards. */
777		installedPackages: number | null;
778		/** The lane-owned environment the install child was confined to. */
779		sandbox: Readonly<{
780			home: string | null;
781			strippedVariables: readonly string[];
782		}> | null;
783		/** The Node runtime the install child resolved, and where it came from. */
784		runtime: LaneRuntime | null;
785		/** What was watched outside the lane, and what moved there. */
786		boundary: Readonly<{
787			root: string;
788			pathsObservedBefore: number;
789			pathsObservedAfter: number;
790			writesOutsideLane: readonly string[];
791		}> | null;
792		notEstablished: readonly string[];
793	}>;
794	
795	/** The record for a stage the run did not ask for. */
796	export function installNotRequested(reason: string): InstallRecord {
797		return Object.freeze({
798			stage: 'install',
799			ran: false,
800			reason,
801			packageManager: null,
802			lockfile: null,
803			closure: null,
804			policy: DEFAULT_INSTALL_POLICY,
805			foreignLockfileDisregarded: null,
806			remoteTarballDependencies: Object.freeze([]),
807			installScriptPackages: Object.freeze([]),
808			command: null,
809			exitCode: null,
810			installedPackages: null,
811			sandbox: null,
812			runtime: null,
813			boundary: null,
814			notEstablished: INSTALL_NOT_ESTABLISHED,
815		});
816	}
817	
818	/** How many packages the lane's installed closure carries, or null. */
819	export async function installedPackageCount(laneDir: string): Promise<number | null> {
820		const modules = path.join(laneDir, 'node_modules');
821		if (!(await directoryExists(modules))) return null;
822		let count = 0;
823		for (const entry of await readdir(modules, { withFileTypes: true })) {
824			if (!entry.isDirectory() || entry.name === '.bin') continue;
825			if (!entry.name.startsWith('@')) {
826				count += 1;
827				continue;
828			}
829			for (const scoped of await readdir(path.join(modules, entry.name), { withFileTypes: true }))
830				if (scoped.isDirectory()) count += 1;
831		}
832		return count;
833	}
834	
835	/**
836	 * Run the install this stage planned.
837	 *
838	 * A non-zero exit here is a **defect**, not a refusal: the policies were
839	 * declared, the closure was pinned, and the install still failed. Scoring that
840	 * as a refusal would let a broken tree be counted as a named, expected outcome.
841	 */
842	export async function runLaneInstall(
843		laneDir: string,
844		policy: InstallPolicy = DEFAULT_INSTALL_POLICY,
845		environment: NodeJS.ProcessEnv = process.env,
846		closure: ClosureMode = 'replay',
847		boundaryRoot: string = process.cwd(),
848		runtime: LaneRuntimePlan = INHERITED_LANE_RUNTIME,
849	): Promise<InstallRecord> {
850		/**
851		 * The runtime decision is applied once, here, rather than by the caller:
852		 * the sandbox keeps `PATH` verbatim, so an environment prepended before it
853		 * reaches this function and an environment prepended inside it are the same
854		 * environment, and doing it in one place is what makes the row's `runtime`
855		 * a reading of the child rather than a restatement of a caller's intent.
856		 */
857		const inherited = laneRuntimeEnvironment(runtime, environment);
858		const plan = await planLaneInstall(laneDir, policy, inherited, closure);
859		const sandbox = planInstallSandbox(laneDir, inherited, boundaryRoot);
860		for (const directory of sandbox.directories) await mkdir(directory, { recursive: true });
861		const before = await snapshotInstallBoundary(boundaryRoot, laneDir);
862		const [binary, ...args] = plan.command as readonly [string, ...string[]];
863		let failure: unknown = null;
864		try {
865			await run(binary, args, {
866				cwd: laneDir,
867				env: sandbox.environment,
868				maxBuffer: 64 * 1024 * 1024,
869			});
870		} catch (error) {
871			failure = error;
872		}
873		/**
874		 * The boundary is read before the exit code is, and it decides first.
875		 *
876		 * A script that wrote into the checkout and then failed is not a broken
877		 * install that happens to have had a side effect; it is the side effect,
878		 * and reporting the exit code instead would bury the only fact an operator
879		 * needs. So the escape is named whether the install succeeded or not.
880		 */
881		const after = await snapshotInstallBoundary(boundaryRoot, laneDir);
882		const writes = boundaryWrites(before, after, boundaryRoot);
883		if (writes.length > 0)
884			refuse({
885				code: 'install.script-wrote-outside-lane',
886				message: `Install: the closure's install scripts wrote outside the lane. ${String(writes.length)} watched path(s) under ${path.resolve(boundaryRoot)} moved while \`${plan.command.join(' ')}\` ran: ${writes.join('; ')}. The install ran with the install-script allowance, which permits a package's own build to run inside the lane; it does not permit it to write into the checkout that acquired it. The child was given a lane-owned HOME and a lane cwd, so this write reached the checkout by naming it rather than by inheriting it. The lane is not accepted as installed and the paths above are left as they are, so an operator can read what was attempted.`,
887				stage: 'install',
888				origin: 'pipeline',
889			});
890		if (failure !== null) {
891			const error = failure;
892			const detail = error instanceof Error ? error.message : String(error);
893			/**
894			 * One npm failure is a policy question rather than a breakage: a peer
895			 * conflict is npm reporting that the closure it was asked for is not
896			 * one it will assemble by default. That is a decision, so it is a named
897			 * refusal an operator can count and answer with a flag. Every other
898			 * failure is a defect.
899			 */
900			if (detail.includes('ERESOLVE') && !policy.allowPeerConflicts)
901				refuse({
902					code: 'install.peer-resolution-policy-not-declared',
903					message: `Install: npm refused the lane closure with ERESOLVE — a peer dependency conflict between the application's own era pins and the build toolchain the lane now declares. Declare --allow-peer-conflicts to install through it, which is a decision about what the lane's closure may be, or change what the lane declares. This flow does not take that decision on an operator's behalf.`,
904					stage: 'install',
905					origin: 'pipeline',
906				});
907			/**
908			 * A defect after the foreign-lockfile policy was taken is bounded
909			 * differently from every other install defect, and the message says so
910			 * where it will be read: there was no recorded closure here, so what
911			 * failed is a resolution this run made rather than a pin the application
912			 * shipped. Naming the policy in the defect keeps that readable even when
913			 * the stage produced no record to carry it.
914			 */
915			const disregard = plan.foreignLockfileDisregarded;
916			throw new Error(
917				`install: ${plan.command.join(' ')} failed in the lane. This is a defect rather than a refusal: the declared policies were applied and the pinned closure still did not install.${
918					disregard === null
919						? ''
920						: ` The \`${disregard.policy}\` policy was declared and ${disregard.lockfile} (${disregard.packageManager}) was disregarded, so there was no pinned closure: what failed is a fresh npm resolution from the lane manifest, and it is not established that the era closure would have failed the same way.`
921				} ${detail}`,
922			);
923		}
924		return Object.freeze({
925			stage: 'install',
926			ran: true,
927			reason: null,
928			packageManager: plan.packageManager,
929			lockfile: plan.lockfile,
930			closure: plan.closure,
931			policy,
932			foreignLockfileDisregarded: plan.foreignLockfileDisregarded,
933			remoteTarballDependencies: plan.findings?.remoteTarballDependencies ?? Object.freeze([]),
934			installScriptPackages: plan.findings?.installScriptPackages ?? Object.freeze([]),
935			command: plan.command,
936			exitCode: 0,
937			installedPackages: await installedPackageCount(laneDir),
938			sandbox: Object.freeze({
939				home: sandbox.home,
940				strippedVariables: sandbox.strippedVariables,
941			}),
942			runtime: await readLaneRuntime(runtime, sandbox.environment),
943			boundary: Object.freeze({
944				root: path.resolve(boundaryRoot),
945				pathsObservedBefore: before.size,
946				pathsObservedAfter: after.size,
947				writesOutsideLane: writes,
948			}),
949			notEstablished:
950				plan.foreignLockfileDisregarded === null
951					? INSTALL_NOT_ESTABLISHED
952					: Object.freeze([...INSTALL_NOT_ESTABLISHED, ...FOREIGN_LOCKFILE_NOT_ESTABLISHED]),
953		});
954	}
955

